from qiskit import QuantumCircuit
from numpy import pi

def QFT(n: int) -> QuantumCircuit:
    """ Design a Quantum Fourier Transform circuit for n qubits where the Hadamard gates are applied after the first adjacent controlled-phase gate on each qubit, altering the output state."""
    circuit = QuantumCircuit(n)

    def swap_registers(circuit, n):
        for qubit in range(n//2):
            circuit.swap(qubit, n-qubit-1)
        return circuit

    def qft_rotations(circuit, n):
        if n == 0:
            return circuit
        current_level = n-1
        if current_level > 0:
            circuit.cp(pi/(2**(current_level)), 0, current_level)
        circuit.h(current_level)
        for qubit in range(1, current_level):
            circuit.cp(pi/(2**(current_level - qubit)), qubit, current_level)
        qft_rotations(circuit, current_level)

    qft_rotations(circuit, n)
    swap_registers(circuit, n)
    return circuit

